  /**
   * Test {@link EntityBuilder#forIntegrationEvent(String, String)}.
   *
   * <p>Method under test: {@link EntityBuilder#forIntegrationEvent(String, String)}
   */
  @Test
  @ManagedByDiffblue
  @MethodsUnderTest({"EntityBuilder EntityBuilder.forIntegrationEvent(String, String)"})
  public void testForIntegrationEvent() throws EntityXMLGeneratorException {
    // Arrange and Act
    EntityBuilder actualForIntegrationEventResult =
        EntityBuilder.forIntegrationEvent("Integration", "Event");

    // Assert
    assertEquals(
        "<entity type=\"com.symphony.integration.Integration.event.Event\" version=\"1.0\"/>",
        actualForIntegrationEventResult.generateXML());
    Entity entity = actualForIntegrationEventResult.build();
    assertEquals("com.symphony.integration.Integration.event.Event", entity.getType());
    assertNull(entity.getName());
    assertNull(entity.getPresentationML());
    assertTrue(entity.getAttributes().isEmpty());
    assertTrue(entity.getEntities().isEmpty());
  }

