  /**
   * Test {@link EntityBuilder#attribute(String, SafeString)} with {@code String}, {@code
   * SafeString}.
   *
   * <p>Method under test: {@link EntityBuilder#attribute(String, SafeString)}
   */
  @Test
  @ManagedByDiffblue
  @MethodsUnderTest({"EntityBuilder EntityBuilder.attribute(String, SafeString)"})
  public void testAttributeWithStringSafeString() throws EntityXMLGeneratorException {
    // Arrange
    EntityBuilder forNestedEntityResult = EntityBuilder.forNestedEntity("Type");

    // Act
    EntityBuilder actualAttributeResult =
        forNestedEntityResult.attribute("Name", SafeString.EMPTY_SAFE_STRING);

    // Assert
    List<Attribute> attributes = actualAttributeResult.build().getAttributes();
    assertEquals(1, attributes.size());
    assertEquals("", attributes.get(0).getValue());
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphonyoss.string\" value=\"\"/"
            + "></entity>",
        actualAttributeResult.generateXML());
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphonyoss.string\" value=\"\"/"
            + "></entity>",
        forNestedEntityResult.generateXML());
  }

  /**
   * Test {@link EntityBuilder#attribute(String, SafeString)} with {@code String}, {@code
   * SafeString}.
   *
   * <p>Method under test: {@link EntityBuilder#attribute(String, SafeString)}
   */
  @Test
  @ManagedByDiffblue
  @MethodsUnderTest({"EntityBuilder EntityBuilder.attribute(String, SafeString)"})
  public void testAttributeWithStringSafeString2() throws EntityXMLGeneratorException {
    // Arrange
    EntityBuilder forNestedEntityResult = EntityBuilder.forNestedEntity("Type");
    forNestedEntityResult.presentationML(SafeString.EMPTY_SAFE_STRING);

    // Act
    EntityBuilder actualAttributeResult =
        forNestedEntityResult.attribute(
            "Name",
            ParserUtils.escapeAndAddLineBreaks(
                "<  a  href  =  \"http://UUUUUUUUUUUU//UU&amp;&amp;//UU&amp;&amp;\"  >xx</a>"));

    // Assert
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><presentationML></presentationML><attribute name=\"Name\" type=\"org"
            + ".symphonyoss.string\" value=\"&amp;lt;  a  href  =  &amp;quot;&lt;a href=&quot;http://UUUUUUUUUUUU//UU"
            + "&amp;amp;amp&quot;&gt;http://UUUUUUUUUUUU//UU&amp;amp;amp&lt;/a&gt;;&amp;amp;amp;//UU&amp;amp;amp;&amp"
            + ";amp;amp;&amp;quot;  &amp;gt;xx&amp;lt;/a&amp;gt;\"/></entity>",
        forNestedEntityResult.generateXML());
    assertSame(forNestedEntityResult, actualAttributeResult);
  }

