    String expectedGenerateXMLResult2 =
        String.join(
            "",
            "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"com.symphony.uri\" value=\"",
            Paths.get(System.getProperty("java.io.tmpdir"), "test.txt").toUri().toString(),
            "\"/></entity>");
    assertEquals(expectedGenerateXMLResult2, forNestedEntityResult.generateXML());
