  /**
   * Test {@link EntityBuilder#attributeIfNotEmpty(String, String)} with {@code String}, {@code
   * String}.
   *
   * <ul>
   *   <li>Then return build Attributes size is one.
   * </ul>
   *
   * <p>Method under test: {@link EntityBuilder#attributeIfNotEmpty(String, String)}
   */
  @Test
  @ManagedByDiffblue
  @MethodsUnderTest({"EntityBuilder EntityBuilder.attributeIfNotEmpty(String, String)"})
  public void testAttributeIfNotEmptyWithStringString_thenReturnBuildAttributesSizeIsOne()
      throws EntityXMLGeneratorException {
    // Arrange
    EntityBuilder forNestedEntityResult = EntityBuilder.forNestedEntity("Type");

    // Act
    EntityBuilder actualAttributeIfNotEmptyResult =
        forNestedEntityResult.attributeIfNotEmpty("Name", "42");

    // Assert
    List<Attribute> attributes = actualAttributeIfNotEmptyResult.build().getAttributes();
    assertEquals(1, attributes.size());
    assertEquals("42", attributes.get(0).getValue());
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphonyoss.string\" value=\"42\"/"
            + "></entity>",
        actualAttributeIfNotEmptyResult.generateXML());
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphonyoss.string\" value=\"42\"/"
            + "></entity>",
        forNestedEntityResult.generateXML());
  }

