  /**
   * Test {@link EntityBuilder#build()}.
   *
   * <p>Method under test: {@link EntityBuilder#build()}
   */
  @Test
  @ManagedByDiffblue
  @MethodsUnderTest({"Entity EntityBuilder.build()"})
  public void testBuild() {
    // Arrange and Act
    Entity actualEntity =
        EntityBuilder.forNestedEntity("Type")
            .presentationML("Presentation ML")
            .presentationML(SafeString.EMPTY_SAFE_STRING)
            .build();

    // Assert
    assertEquals("", actualEntity.getPresentationML());
    assertEquals("Type", actualEntity.getType());
    assertNull(actualEntity.getName());
    assertTrue(actualEntity.getAttributes().isEmpty());
    assertTrue(actualEntity.getEntities().isEmpty());
  }

